      response = await handleOpenAIUsageLimit({ client, originalFetch, input, init: firstInit, response, retryInput });
    }
    if (await isOpenAIOverloadResponse(response)) {
      response = await handleOpenAIOverload({ originalFetch, init: firstInit, response, retryInput });
    }
    if (response.ok) {
      return wrapOpenAIOverloadStream({ originalFetch, response, retryInput, init: firstInit });
