When modifying the response body by appending a recovery note, the original `content-length` header becomes inaccurate. It is best practice to remove this header so that the `Response` constructor can automatically calculate the correct length for the new body, preventing potential truncation or protocol errors in some clients.

```javascript
export async function annotateOpenAIOverloadResponse(response) {
  try {
    const text = await response.text();
    const annotated = annotateOpenAIOverloadText(text);
    const headers = new Headers(response.headers);
    headers.delete("content-length");
    return new Response(annotated, {
      status: response.status,
      statusText: response.statusText,
      headers,
    });
  } catch {
    return response;
  }
}
